/**
 * Typed accessors for the build-time content snapshot.
 *
 * The snapshot is generated by `scripts/export-content.mjs` from published
 * Supabase rows. It is bundled into both the client and SSR builds, so public
 * pages never need a runtime backend call to render content.
 */
import snapshotJson from "./content-snapshot.json";
import manifestJson from "./content-snapshot.manifest.json";
import type {
  CaseStudy,
  FAQItem,
  GalleryItem,
  HubDetail,
  IndustryItem,
  StatItem,
  TeamMember,
  Testimonial,
} from "./logisticsData";

export type SnapshotRow = Record<string, any>;

export interface ContentSnapshot {
  schemaVersion: number;
  contentVersion: string;
  generatedAt: string;
  source: string;
  checksum: string;
  tables: Record<string, SnapshotRow[]>;
}

export interface SnapshotManifest {
  schemaVersion: number;
  contentVersion: string;
  generatedAt: string;
  source: string;
  checksum: string;
  totalRecords: number;
  counts: Record<string, number>;
  files: Record<string, string>;
}

const SNAPSHOT = snapshotJson as unknown as ContentSnapshot;
export const SNAPSHOT_MANIFEST = manifestJson as unknown as SnapshotManifest;

export const SNAPSHOT_META = {
  schemaVersion: SNAPSHOT.schemaVersion,
  contentVersion: SNAPSHOT.contentVersion,
  generatedAt: SNAPSHOT.generatedAt,
  source: SNAPSHOT.source,
  checksum: SNAPSHOT.checksum,
  totalRecords: SNAPSHOT_MANIFEST.totalRecords,
  counts: SNAPSHOT_MANIFEST.counts,
};

export function getTableRows(table: string): SnapshotRow[] {
  const rows = SNAPSHOT.tables?.[table];
  return Array.isArray(rows) ? rows : [];
}

export const SNAPSHOT_SITE_CONTENT: Record<string, string> = Object.fromEntries(
  getTableRows("site_content")
    .filter((row) => row.content_key)
    .map((row) => [String(row.content_key), String(row.content_value ?? "")])
);

export const SNAPSHOT_SITE_SETTINGS: Record<string, string> = Object.fromEntries(
  getTableRows("site_settings")
    .filter((row) => row.setting_key)
    .map((row) => [String(row.setting_key), String(row.setting_value ?? "")])
);

/** Aliases kept for components written against the flat site_content keys. */
const CONTENT_SETTING_ALIASES: Record<string, string> = {
  contact_email: "primaryEmail",
  contact_phone: "phone",
  contact_address: "headOffice",
  contact_whatsapp: "whatsapp",
};

export function getSnapshotSiteContent(key: string, fallback = ""): string {
  const direct = SNAPSHOT_SITE_CONTENT[key];
  if (direct !== undefined && direct.trim() !== "") return direct;
  const alias = CONTENT_SETTING_ALIASES[key];
  if (alias) {
    const value = SNAPSHOT_SITE_SETTINGS[alias];
    if (value !== undefined && value.trim() !== "") return value;
  }
  return fallback;
}

export function getSnapshotSiteSetting(key: string, fallback = ""): string {
  const value = SNAPSHOT_SITE_SETTINGS[key];
  return value !== undefined && value.trim() !== "" ? value : fallback;
}

