export function getSnapshotServiceRows(): SnapshotRow[] {
  return getTableRows("services").filter((row) => row.is_published !== false);
}

export function getSnapshotServiceItemRows(): SnapshotRow[] {
  return getTableRows("service_items").filter((row) => row.is_published !== false);
}

export function getSnapshotServiceFaqs(): SnapshotRow[] {
  return getTableRows("service_faqs");
}

export function getSnapshotServiceProcessSteps(): SnapshotRow[] {
  return getTableRows("service_process_steps");
}

export function getSnapshotServiceShowcase(): SnapshotRow[] {
  return getTableRows("service_visual_showcase");
}

export function getSnapshotServiceCargo(): SnapshotRow[] {
  return getTableRows("service_cargo_applications");
}

/* ------------------------------------------------------------------ */
/* Company + marketing entities                                        */
/* ------------------------------------------------------------------ */

export const SNAPSHOT_COMPANY_OVERRIDES: Record<string, string> = Object.fromEntries(
  Object.entries({
    name: SNAPSHOT_SITE_SETTINGS.name,
    tagline: SNAPSHOT_SITE_SETTINGS.tagline,
    secondaryTagline: SNAPSHOT_SITE_SETTINGS.secondaryTagline,
    primaryEmail: SNAPSHOT_SITE_SETTINGS.primaryEmail,
    secondaryEmail: SNAPSHOT_SITE_SETTINGS.secondaryEmail,
    phone: SNAPSHOT_SITE_SETTINGS.phone,
    secondaryPhone: SNAPSHOT_SITE_SETTINGS.secondaryPhone,
    whatsapp: SNAPSHOT_SITE_SETTINGS.whatsapp,
    headOffice: SNAPSHOT_SITE_SETTINGS.headOffice,
    aboutShort: SNAPSHOT_SITE_SETTINGS.aboutShort,
    aboutDetailed: SNAPSHOT_SITE_SETTINGS.aboutDetailed,
  }).filter(([, value]) => typeof value === "string" && value.trim() !== "")
);

const FALLBACK_IMAGE =
  "https://res.cloudinary.com/uorctww6/image/upload/v1789377038/arrowline/general/hero-logistics.jpg";

function imageOrFallback(value: unknown): string {
  return typeof value === "string" && value.trim() !== "" ? value : FALLBACK_IMAGE;
}

export const SNAPSHOT_INDUSTRIES: IndustryItem[] = getTableRows("industries").map((row) => ({
  id: String(row.slug || row.id),
  title: String(row.title || ""),
  description: String(row.description || ""),
  icon: String(row.icon || "Layers"),
  cargoTypes: Array.isArray(row.cargo_types) ? row.cargo_types.map(String) : [],
  image: imageOrFallback(row.image),
}));

export const SNAPSHOT_FAQS: FAQItem[] = getTableRows("faqs").map((row) => ({
  id: String(row.id),
  question: String(row.question || ""),
  answer: String(row.answer || ""),
  category: String(row.category || "General"),
}));

export const SNAPSHOT_TESTIMONIALS: Testimonial[] = getTableRows("testimonials").map((row) => ({
  id: String(row.id),
  clientName: String(row.customer_name || ""),
  company: String(row.company || ""),
  role: String(row.position || ""),
  location: "",
  comment: String(row.testimonial || ""),
  rating: Number(row.rating) || 5,
  serviceUsed: "",
  avatar: typeof row.photo === "string" ? row.photo : "",
}));

export const SNAPSHOT_GALLERY: GalleryItem[] = getTableRows("gallery_items").map((row) => ({
  id: String(row.id),
  title: String(row.title || ""),
  category: (String(row.category || "Mundra Port") as GalleryItem["category"]),
  image: imageOrFallback(row.image),
  alt: String(row.alt_text || row.title || ""),
  caption: String(row.description || ""),
}));

export const SNAPSHOT_CASE_STUDIES: CaseStudy[] = getTableRows("case_studies").map((row) => ({
  id: String(row.slug || row.id),
  title: String(row.title || ""),
  service: String(row.industry || "Logistics"),
  location: String(row.location || ""),
  clientSector: String(row.industry || ""),
  summary: String(row.description || ""),
  challenge: String(row.challenge || ""),
  solution: String(row.solution || ""),
  result: String(row.results || ""),
  image: imageOrFallback(row.featured_image),
  badge: String(row.industry || "Case Study"),
}));

export const SNAPSHOT_TEAM: TeamMember[] = getTableRows("leadership").map((row) => {
  const alt = String(row.image_alt || "");
  // Some CMS rows keep the role in alt text (e.g. "Name — Role").
  const altRole = alt.includes("—") ? alt.split("—").slice(1).join("—").trim() : "";
  return {
    name: String(row.name || ""),
    role: String(row.role || altRole || ""),
    location: String(row.location || ""),
    email: String(row.email || ""),
    image: imageOrFallback(row.image),
    bio: String(row.bio || ""),
  };
});

export const SNAPSHOT_CORE_VALUES = getTableRows("core_values").map((row) => ({
  title: String(row.title || ""),
  desc: String(row.description || ""),
  icon: String(row.icon || "ShieldCheck"),
}));

export const SNAPSHOT_STATS: StatItem[] = getTableRows("statistics").map((row) => ({
  number: String(row.value || ""),
  label: String(row.label || ""),
  sublabel: String(row.description || ""),
  iconName: String(row.icon || "Activity"),
}));

export interface SnapshotTrustLogo {
  logoType: string;
  name: string;
  logo: string;
  description?: string;
}

export const SNAPSHOT_TRUST_LOGOS: SnapshotTrustLogo[] = getTableRows("trusted_network")
  .filter((row) => typeof row.logo === "string" && row.logo.trim() !== "")
  .map((row) => ({
    logoType: String(row.name || ""),
    name: String(row.category || "Trusted partner"),
    logo: String(row.logo),
    description: row.description ? String(row.description) : undefined,
  }));

export function buildSnapshotHubs(staticHubs: HubDetail[]): HubDetail[] {
  const rows = getTableRows("locations");
  if (rows.length === 0) return staticHubs;
  return rows.map((row) => {
    const fallback = staticHubs.find((hub) => hub.id === row.slug) || staticHubs[0];
    return {
      id: String(row.slug || row.id),
      name: String(row.name || ""),
      state: String(row.state || fallback?.state || ""),
      type: (fallback?.type || "Regional Office") as HubDetail["type"],
      coordinates: fallback?.coordinates || { x: 50, y: 50 },
      details: String(row.description || fallback?.details || ""),
      connectivity: String(row.address || fallback?.connectivity || ""),
    };
  });
}

