function contentImage(key: string, fallback = ""): string {
  const value = SNAPSHOT_SITE_CONTENT[key];
  return typeof value === "string" && value.trim() !== "" ? value : fallback;
}

export const SNAPSHOT_ABOUT = {
  siteContent: SNAPSHOT_SITE_CONTENT,
  images: [
    ...getTableRows("about_images").map((row) => ({
      ...row,
      image_url: row.image_url || "",
      alt_text: row.alt_text || "",
    })),
    {
      id: "site-content-hero",
      slot: "hero",
      image_url: contentImage("about_image"),
      alt_text: "Arrowline Logistics multimodal freight corridor across India",
      is_published: true,
    },
  ].filter((image) => Boolean(image.image_url)),
  pillars: getTableRows("about_pillars"),
  milestones: getTableRows("about_milestones"),
  differentiators: getTableRows("about_differentiators"),
};
